\draw[black,->] (0,0)--(7.6,0);
\draw[black,->] (0,0)--(0,45);
\foreach \t in {1,2,3,4,5,6,7} {\draw[black] (\t,0)--++(0,-.6);\node[below,font=\fontsize{8.5}{10}\selectfont] at (\t,-.6) {\special{dvisvgm:raw <g data-graph-text="tick">}$\t$\special{dvisvgm:raw </g>}};}
